import {dimH,dimV,escapeMarkup as esc,inch} from './cabinet-drawings.js';
import {downloadFile} from './kitchen-workshop.js';
import {STAIR_ASSUMPTIONS,STAIR_LIMITS,stairStudy,stairExcelInputs} from './stair-calculations.js';
export {STAIR_ASSUMPTIONS,stairStudy};
export function stairSVG(input={}){
 const s=stairStudy(input),start=s.length-s.requiredLength,landingX=s.length-s.width,flightY=s.depth-s.width,exitY=s.depth-s.requiredDepth,minX=Math.min(0,start-s.width,s.length-s.openingLength),minY=Math.min(0,exitY-s.width,s.depth-s.openingDepth),scale=Math.min(3,550/(s.length-minX),350/(s.depth-minY)),x0=65-minX*scale,y0=155-minY*scale,X=n=>x0+n*scale,Y=n=>y0+n*scale;
 const rect=(x,y,w,h,fill,stroke='#355963',dash='')=>`<rect x="${X(x)}" y="${Y(y)}" width="${w*scale}" height="${h*scale}" fill="${fill}" stroke="${stroke}" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;
 const line=(x,y,x2,y2)=>`<path d="M${X(x)} ${Y(y)}L${X(x2)} ${Y(y2)}" stroke="#5b7375" fill="none"/>`;
 const text=(x,y,t,size=14)=>`<text x="${x}" y="${y}" font-size="${size}" fill="#24434a">${esc(t)}</text>`;
 let out=`<svg class="makerDrawing" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 820" role="img" aria-label="L shaped stair feasibility plan"><defs><marker id="stairArrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#295e63"/></marker></defs><rect width="1000" height="820" fill="#fbfcfa"/><g font-family="Arial">`;
 out+=text(35,35,'L-SHAPED STAIR | Front-side entry, left turn down',22)+text(35,62,'Feasibility only. September 22 plan envelope traced to scale; field opening and floor rise unconfirmed.',13);
 out+=rect(0,0,s.length,s.depth,'#edf0ea','#8c9690','8 5');
 out+=rect(s.length-s.openingLength,s.depth-s.openingDepth,s.openingLength,s.openingDepth,'none','#356eaa','4 3');
 out+=rect(start-s.width,flightY,s.width,s.width,'#f1e6d5','#ad9570','5 4')+rect(landingX,exitY-s.width,s.width,s.width,'#f1e6d5','#ad9570','5 4');
 out+=rect(start,flightY,s.firstRun,s.width,'#d5e3db')+rect(landingX,flightY,s.width,s.width,'#c7d8cc')+rect(landingX,exitY,s.width,s.secondRun,'#d9e6e0');
 for(let i=1;i<s.upper;i++)out+=line(start+(i-1)*s.going,flightY,start+(i-1)*s.going,s.depth);
 for(let i=1;i<s.lower;i++)out+=line(landingX,flightY-i*s.going,s.length,flightY-i*s.going);
 out+=`<path d="M${X(start-s.width*.7)} ${Y(flightY+s.width/2)}H${X(landingX+s.width/2)}V${Y(exitY-s.width*.5)}" fill="none" stroke="#295e63" stroke-width="3" marker-end="url(#stairArrow)"/>`;
 out+=text(X(start-s.width)+4,Y(flightY)-14,'ENTRY from main hall',13)+text(X(landingX)-12,Y(exitY-s.width)-13,'Exit into basement game room',13);
 out+=text(X(start+3),Y(s.depth)+25,s.upper+' risers down, then '+s.lower+' risers',14);
 out+=dimH(X(start),X(s.length),Y(s.depth)+60,inch(s.requiredLength)+' required')+dimV(X(s.length)+32,Y(exitY),Y(s.depth),inch(s.requiredDepth)+' required');
 out+=text(700,166,'FLOOR-TO-FLOOR RISE',14)+text(700,193,inch(s.rise),22)+text(700,234,s.risers+' risers at '+inch(s.riser),14)+text(700,261,inch(s.going)+' tread going',14)+text(700,288,inch(s.width)+' clear stair / turn',14);
 out+=text(700,337,'AVAILABLE FOOTPRINT',14)+text(700,364,inch(s.length)+' x '+inch(s.depth),17)+text(700,397,s.planFits?'Fits in plan, subject to review':'Needs '+inch(s.extraLength)+' more length',14);
 out+=text(700,434,'FLOOR OPENING',14)+text(700,461,inch(s.openingLength)+' x '+inch(s.openingDepth),17)+text(700,488,'Blue dashed line',13);
 out+=text(35,625,'Orientation: front door toward the bottom / left. Enter the front-side flight from the hall.',14)+text(35,652,'Travel east, turn left at a square landing, then descend north toward the basement game room.',14);
 out+=text(35,691,'Dashed tan squares: '+inch(s.width)+' top / bottom landing reservations, outside the flight footprint.',13)+text(35,716,'Ceiling '+inch(s.clearBelow)+'; floor / ceiling zone '+inch(s.assembly)+'. Headroom target '+inch(s.headroomTarget)+'.',13)+text(35,750,'Opening shares the front/right datum. Smaller openings require headroom checks beneath the remaining floor.',13)+text(35,778,'Designer and builder must confirm the opening and applicable local code before the stair is changed.',13);
 return out+'</g></svg>';
}
export function mountStairStudy(){
 const button=document.getElementById('stairStudy'),dialog=document.getElementById('stairStudyDialog'),host=document.getElementById('stairStudyContent');let values={...STAIR_ASSUMPTIONS};
 try{const saved=JSON.parse(localStorage.getItem('brines-stair-study-v2'));if(saved){stairStudy(saved);values={...values,...saved};}}catch{}
 function save(){try{localStorage.setItem('brines-stair-study-v2',JSON.stringify(values));}catch{}}
 function render(){const s=stairStudy(values);host.innerHTML=`<p>Enter from the main hall at the end closest to the front door, descend right, turn left, then descend toward the basement game room.</p><p class="note">The September 22 plan gives an approximately 132 × 97.25 inch traced stair envelope. The starting opening and height values below are assumptions, not field measurements. <a href="assets/review-plans-2026-09-22.pdf" target="_blank" rel="noopener">Open source plans</a>.</p><label class="field">Height measurement method<select id="stairHeightMode"><option value="ceiling">Basement ceiling height + floor / ceiling zone</option><option value="rise">Direct finished floor-to-floor measurement</option></select></label><div class="stairInputs"></div><p class="note">Ceiling height is basement finished floor to finished ceiling. The floor / ceiling zone runs from that ceiling to the upper finished floor and includes joists, decking, finishes and any dropped ceiling. Use the same finished-surface datum for both measurements.</p><div class="makerButtons"><button data-preset="comfortable">10.5-inch tread / 7.5-inch max riser</button><button data-preset="compact">10-inch tread / 7.75-inch max riser</button><button id="stairMatchOpening">Match opening to available footprint</button></div><p class="${s.planFits?'kFit':'kWarning'}">${s.planFits?'Flights fit the available footprint in plan.':'Flights need '+inch(s.extraLength)+' more length'+(s.extraDepth?' and '+inch(s.extraDepth)+' more depth':'')+'.'} Floor-to-floor rise ${inch(s.rise)}. ${s.risers} risers at ${inch(s.riser)}: ${s.upper} before the turn and ${s.lower} after.</p><p class="${s.openingCoversFlights?'kFit':'kWarning'}">${s.openingCoversFlights?'The entered opening covers both flights and the turn in plan.':'Opening is '+inch(s.openingShortLength)+' short in length and '+inch(s.openingShortDepth)+' short in depth of full-flight coverage. A smaller opening may still work, but it needs a headroom section.'}</p><div class="measurementPreview">${stairSVG(values)}</div>${s.clearBelow<s.headroomTarget?'<p class="kWarning">The entered heights leave less clear space below the ceiling than the headroom target.</p>':''}<p>Below an intact floor / ceiling zone, at least ${s.headroomRisers} risers of descent would be needed to reach the ${inch(s.headroomTarget)} headroom target. This screening calculation does not verify the header position or clearance along every tread.</p><p class="note">The opening and available footprint share the front/right corner in this study. Top and bottom landings need space outside the flights. The original modeled stairs are unchanged. Confirm framing, opening location, handrails, guards and a measured section with the designer.</p><p class="note">Reference: <a href="https://bouldercounty.gov/property-and-land/land-use/building/building-publications/residential-stairways-handrails-ramps-and-guards-b32/" target="_blank" rel="noopener">official IRC stair guide</a>. Screening limits are 36-inch width, 7.75-inch maximum riser, 10-inch tread and at least 80-inch headroom. Local project requirements still need confirmation.</p><div class="makerButtons"><button id="downloadStairSVG">Download measured drawing</button><a class="stairExcelLink" href="exports/Brines-Stair-Calculator.xlsx" download>Download Excel calculator</a><button id="copyStairInputs">Copy these inputs for Excel</button></div><p class="note">Excel recalculates dimensions and the plan diagram. Its starting values match the reference example. To transfer this configuration, copy the inputs above and paste into cell C15 of the Stair study sheet.</p><p id="stairCopyStatus" role="status"></p>`;
 const mode=host.querySelector('#stairHeightMode');mode.value=values.heightMode;mode.onchange=()=>{if(mode.value==='rise')values.rise=s.rise;else values.ceilingHeight=s.clearBelow;values.heightMode=mode.value;save();render();};
 const fields=[['ceilingHeight','Basement floor to ceiling (in)'],['assembly','Ceiling to upper finished floor (in)'],['rise','Direct floor-to-floor rise (in)'],['length','Available stair footprint length (in)'],['depth','Available stair footprint depth (in)'],['openingLength','Clear floor opening length (in)'],['openingDepth','Clear floor opening depth (in)'],['width','Stair clear width (in)'],['going','Tread going (in)'],['maxRiser','Maximum target riser (in)'],['headroomTarget','Headroom target (in)']];
 const grid=host.querySelector('.stairInputs');for(const [key,label] of fields){const [min,max]=STAIR_LIMITS[key],lab=document.createElement('label');lab.className='field';lab.textContent=label;const input=document.createElement('input');Object.assign(input,{type:'number',min,max,step:key==='maxRiser'?.125:.25,value:values[key],disabled:(key==='rise'&&values.heightMode==='ceiling')||(key==='ceilingHeight'&&values.heightMode==='rise')});if(input.disabled){input.value=key==='rise'?s.rise:s.clearBelow;lab.classList.add('inactiveInput');}input.onchange=()=>{if(input.value!==''&&Number.isFinite(Number(input.value))){values[key]=Math.min(max,Math.max(min,Number(input.value)));save();render();}else input.value=values[key];};lab.append(input);grid.append(lab);}
 host.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{values.going=b.dataset.preset==='compact'?10:10.5;values.maxRiser=b.dataset.preset==='compact'?7.75:7.5;save();render();});
 host.querySelector('#stairMatchOpening').onclick=()=>{values.openingLength=values.length;values.openingDepth=values.depth;save();render();};host.querySelector('#downloadStairSVG').onclick=()=>downloadFile(stairSVG(values),'brines-90-degree-stair-study.svg','image/svg+xml');
 host.querySelector('#copyStairInputs').onclick=async()=>{const text=stairExcelInputs(values).join('\n');try{await navigator.clipboard.writeText(text);host.querySelector('#stairCopyStatus').textContent='Copied. Paste into cell C15 in Excel.';}catch{downloadFile(text,'brines-stair-inputs.tsv','text/tab-separated-values');host.querySelector('#stairCopyStatus').textContent='Downloaded input column. Copy its values into cell C15 in Excel.';}};
 }
 button.onclick=()=>{render();dialog.showModal();};return {render};
}
